$(document).ready(function(){$(".alert").delay(5e3).slideUp(200,function(){$(this).alert('close')});$(document).on('click','[data-toggle="lightbox"]',function(e){e.preventDefault(),$(this).ekkoLightbox()});$(document).on('contextmenu',function(e){e.preventDefault()});$('img').on('dragstart',function(e){e.preventDefault()})});function filterGallery(e){Array.from(document.getElementsByClassName('gallery-item')).forEach(t=>{t.classList.toggle('show',e==='all'||t.classList.contains(e))})}function acceptCookies(){localStorage.setItem('cookiesAccepted','true'),document.getElementById('cookie-banner').style.display='none'}window.onload=function(){localStorage.getItem('cookiesAccepted')==='true'&&(document.getElementById('cookie-banner').style.display='none')};function getCSRFToken(){return document.querySelector('meta[name="csrf-token"]').getAttribute('content')}function deleteImage(e,t){const o=`${t}`;Swal.fire({title:"Sei sicuro?",text:"Questa azione è irreversibile!",icon:"warning",showCancelButton:!0,confirmButtonColor:"#d33",cancelButtonColor:"#3085d6",confirmButtonText:"Sì, elimina!",cancelButtonText:"Annulla"}).then(t=>{t.isConfirmed&&fetch(`/delete-image/${encodeURIComponent(o)}`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':getCSRFToken()}}).then(e=>e.ok?e.json():e.text().then(t=>{throw new Error(`Errore HTTP ${e.status}: ${t}`)})).then(e=>{e.success?Swal.fire({title:"Eliminata!",text:"L'immagine è stata eliminata con successo.",icon:"success",confirmButtonColor:"#3085d6"}).then(()=>window.location.reload()):Swal.fire({title:"Errore!",text:"Non è stato possibile eliminare l'immagine.",icon:"error",confirmButtonColor:"#d33"})}).catch(e=>{Swal.fire({title:"Errore di connessione!",text:e.message,icon:"error",confirmButtonColor:"#d33"})})})}function moveImage(e){var t=e.dataset.filename,o=e.dataset.category.replace("img/gallery/",""),n=e.value,a=`${t}`,i=`img/gallery/${n}/${t}`;a===i?Swal.fire({title:"⚠️ Attenzione!",text:"L'immagine è già in questa categoria!",icon:"warning",confirmButtonColor:"#3085d6"}):Swal.fire({title:"Sicuro di voler spostare l'immagine?",text:`L'immagine verrà spostata da ${o} a ${n}.`,icon:"question",showCancelButton:!0,confirmButtonColor:"#28a745",cancelButtonColor:"#d33",confirmButtonText:"Sì, sposta!",cancelButtonText:"Annulla"}).then(e=>{e.isConfirmed&&fetch('/move-image',{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':getCSRFToken()},body:JSON.stringify({src_public_id:a,dest_public_id:i})}).then(e=>e.ok?e.json():e.text().then(t=>{throw new Error(`Errore HTTP ${e.status}: ${t}`)})).then(e=>{e.success?Swal.fire({title:"Spostato!",text:"L'immagine è stata spostata con successo.",icon:"success",confirmButtonColor:"#3085d6"}).then(()=>window.location.reload()):Swal.fire({title:"Errore!",text:"Non è stato possibile spostare l'immagine.",icon:"error",confirmButtonColor:"#d33"})}).catch(e=>{Swal.fire({title:"Errore di connessione!",text:e.message,icon:"error",confirmButtonColor:"#d33"})})})}
